public List<Integer> primesUpTo(int n) {
    List<Integer> primes = new ArrayList<>();
    for (int x = 2; x <= n; x++) {
        if (isPrime(x)) {
            primes.add(x);
        }
    }
    return primes;
}

private boolean isPrime(int x) {
    if (x < 2) return false;
    for (long d = 2; d * d <= x; d++) {
        if (x % d == 0) return false;
    }
    return true;
}

